use ratatui::{prelude::*, widgets::*}; use crate::app::App; pub fn draw(f:&mut Frame, app:&App, area:Rect, text:&str){ let mode=format!("{:?}", app.mode).to_uppercase(); let p=Paragraph::new(format!(" {} │ {} │ {} transfer(s) │ {}", mode, app.current_host().map(|h|h.alias.as_str()).unwrap_or("no host"), app.transfer_queue.active_count(), text)).style(Style::default().bg(app.theme.surface).fg(app.theme.fg)); f.render_widget(p, area); }